/* v8.0.4 小人兜底图 + 永久缓存
   - 视频未加载完成前先用内嵌 base64 图片（透明 PNG，9:16）
   - 视频地址成功加载后写入 Cache API，下次刷新/重进直接读本地缓存
   - 注册 Service Worker：CSS/JS/图片 缓存优先，永久保存（手动清除才失效） */
window.SL_CHAR_POSTER='data:image/png;base64,';
(function(){
  var isWeb = /^(http|https):/.test(location.protocol) && !/^(127\.0\.0\.1|localhost)$/.test(location.hostname);
  function setPoster(v){ try{ if(v && !v.poster) v.poster = window.SL_CHAR_POSTER; }catch(e){} }
  function cacheVideo(v){
    if(!('caches' in window)) return;
    var src = v.getAttribute('src'); if(!src || /^blob:/.test(src)) return;
    var abs; try{ abs = new URL(src, location.href).href; }catch(e){ return; }
    if(!/^https?:/.test(abs) || v.__slCachedUrl === abs) return;
    v.__slCachedUrl = abs;
    caches.open('sl-assets-v1').then(function(c){
      return c.match(abs).then(function(r){ return r || fetch(abs).then(function(res){ if(res.ok) c.put(abs,res.clone()); return res; }); });
    }).then(function(r){ return r.blob(); }).then(function(b){
      var u = URL.createObjectURL(b), playing = !v.paused;
      v.src = u; if(playing){ try{ v.play().catch(function(){}); }catch(e){} }
    }).catch(function(){ v.__slCachedUrl=''; });
  }
  function boot(){
    ['slChar','chatChar'].forEach(function(id){
      var v = document.getElementById(id); if(!v) return;
      setPoster(v);
      if(isWeb){
        cacheVideo(v);
        setInterval(function(){ setPoster(v); cacheVideo(v); }, 5000);
      }
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();
  setTimeout(boot,800);
})();
(function(){
  if(!('serviceWorker' in navigator) || !/^https?:/.test(location.protocol)) return;
  try{
    var depth = location.pathname.split('/').length - 2;
    var rel = depth > 0 ? '../'.repeat(depth) + 'sw.js' : 'sw.js';
    navigator.serviceWorker.register(rel, { scope: '/' }).catch(function(){});
  }catch(e){}
})();